ALTER TABLE bookings ADD transport_mode TEXT NOT NULL DEFAULT '' CHECK(transport_mode IN ('','walking','bicycle','ebike','public_transit','car','taxi','other'));
--> statement-breakpoint
ALTER TABLE bookings ADD estimated_cost_cents INTEGER CHECK(estimated_cost_cents IS NULL OR (estimated_cost_cents BETWEEN 0 AND 10000000 AND estimated_cost_cents=CAST(estimated_cost_cents AS INTEGER)));
--> statement-breakpoint
DROP TRIGGER booking_notice;
--> statement-breakpoint
CREATE TRIGGER booking_notice AFTER UPDATE OF status ON bookings WHEN NEW.status IN ('approved','rejected') AND OLD.status!=NEW.status BEGIN
 INSERT INTO notices(user_id,booking_id,message,created) VALUES(NEW.user_id,NEW.id,( CASE  WHEN NEW.status='approved' THEN '你的预约已批准。' ELSE '你的预约已拒绝。拒绝理由：'||COALESCE(NULLIF(NEW.reason,''),'未填写理由')  END )||char(10)||'姓名：'||NEW.name||char(10)||'餐厅：'||NEW.restaurant||char(10)||'用餐时间（北京时间）：'||strftime('%Y/%m/%d %H:%M',NEW.meal_at,'+8 hours')||char(10)||'餐次：'|| CASE  NEW.meal_type WHEN 'lunch' THEN '午餐' WHEN 'dinner' THEN '晚餐' WHEN 'late' THEN '夜宵' ELSE '未注明'  END ||char(10)||'人数：'||NEW.party_size||char(10)||'同行人：'||COALESCE(NULLIF(NEW.companions,''),'未填写')||char(10)||'联系方式：'||COALESCE(NULLIF(NEW.contact,''),'未填写')||char(10)||'地址：'||COALESCE(NULLIF(NEW.address,''),'未填写')||char(10)||'备注：'||COALESCE(NULLIF(NEW.notes,''),'无')||char(10)||'王亦达摄入热量：'|| CASE  WHEN NEW.calories IS NULL THEN '待补填' ELSE NEW.calories||' 千卡'  END ||char(10)||'交通方式：'|| CASE NEW.transport_mode WHEN 'walking' THEN '步行' WHEN 'bicycle' THEN '骑行' WHEN 'ebike' THEN '电动车' WHEN 'public_transit' THEN '公共交通' WHEN 'car' THEN '自驾' WHEN 'taxi' THEN '打车' WHEN 'other' THEN '其他' ELSE '未填写' END ||char(10)||'预估人均消费：'|| CASE WHEN NEW.estimated_cost_cents IS NULL THEN '未填写' ELSE printf('%.2f 元/人',NEW.estimated_cost_cents/100.0) END ,strftime('%Y-%m-%dT%H:%M:%fZ','now'));
 END ;
