CREATE TRIGGER cancellation_notice AFTER UPDATE OF status ON bookings WHEN OLD.status='approved' AND NEW.status='cancelled' BEGIN
 INSERT INTO notices(user_id,booking_id,message,created) SELECT id,NEW.id,'预约人已取消获批预约，原预约周名额已返还。'||char(10)||'姓名：'||NEW.name||char(10)||'餐厅：'||NEW.restaurant||char(10)||'用餐时间（北京时间）：'||strftime('%Y/%m/%d %H:%M',NEW.meal_at,'+8 hours')||char(10)||'餐次：'|| CASE  NEW.meal_type WHEN 'lunch' THEN '午餐' WHEN 'dinner' THEN '晚餐' WHEN 'late' THEN '夜宵' ELSE '未注明'  END ||char(10)||'人数：'||NEW.party_size||char(10)||'同行人：'||COALESCE(NULLIF(NEW.companions,''),'未填写')||char(10)||'联系方式：'||COALESCE(NULLIF(NEW.contact,''),'未填写')||char(10)||'地址：'||COALESCE(NULLIF(NEW.address,''),'未填写')||char(10)||'备注：'||COALESCE(NULLIF(NEW.notes,''),'无')||char(10)||'王亦达摄入热量：'|| CASE  WHEN NEW.calories IS NULL THEN '待补填' ELSE NEW.calories||' 千卡'  END ||char(10)||'交通方式：'|| CASE NEW.transport_mode WHEN 'walking' THEN '步行' WHEN 'bicycle' THEN '骑行' WHEN 'ebike' THEN '电动车' WHEN 'public_transit' THEN '公共交通' WHEN 'car' THEN '自驾' WHEN 'taxi' THEN '打车' WHEN 'other' THEN '其他' ELSE '未填写' END ||char(10)||'预估人均消费：'|| CASE WHEN NEW.estimated_cost_cents IS NULL THEN '未填写' ELSE printf('%.2f 元/人',NEW.estimated_cost_cents/100.0) END ,strftime('%Y-%m-%dT%H:%M:%fZ','now') FROM users WHERE role='admin' AND NEW.cancelled_by=NEW.user_id;
 INSERT INTO notices(user_id,booking_id,message,created) SELECT NEW.user_id,NEW.id,'王亦达已取消你的获批预约，原预约周名额已返还。'||char(10)||'姓名：'||NEW.name||char(10)||'餐厅：'||NEW.restaurant||char(10)||'用餐时间（北京时间）：'||strftime('%Y/%m/%d %H:%M',NEW.meal_at,'+8 hours')||char(10)||'餐次：'|| CASE  NEW.meal_type WHEN 'lunch' THEN '午餐' WHEN 'dinner' THEN '晚餐' WHEN 'late' THEN '夜宵' ELSE '未注明'  END ||char(10)||'人数：'||NEW.party_size||char(10)||'同行人：'||COALESCE(NULLIF(NEW.companions,''),'未填写')||char(10)||'联系方式：'||COALESCE(NULLIF(NEW.contact,''),'未填写')||char(10)||'地址：'||COALESCE(NULLIF(NEW.address,''),'未填写')||char(10)||'备注：'||COALESCE(NULLIF(NEW.notes,''),'无')||char(10)||'王亦达摄入热量：'|| CASE  WHEN NEW.calories IS NULL THEN '待补填' ELSE NEW.calories||' 千卡'  END ||char(10)||'交通方式：'|| CASE NEW.transport_mode WHEN 'walking' THEN '步行' WHEN 'bicycle' THEN '骑行' WHEN 'ebike' THEN '电动车' WHEN 'public_transit' THEN '公共交通' WHEN 'car' THEN '自驾' WHEN 'taxi' THEN '打车' WHEN 'other' THEN '其他' ELSE '未填写' END ||char(10)||'预估人均消费：'|| CASE WHEN NEW.estimated_cost_cents IS NULL THEN '未填写' ELSE printf('%.2f 元/人',NEW.estimated_cost_cents/100.0) END ,strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE NEW.cancelled_by IN (SELECT id FROM users WHERE role='admin');
 END ;
