CREATE TRIGGER manager_cancel_notice AFTER UPDATE OF status ON bookings WHEN NEW.status='cancelled' AND OLD.status!='cancelled' AND NEW.cancelled_by IN (SELECT id FROM users WHERE role='manager') BEGIN
